"""Scenario library: built-in scenarios (scenarios/*.json, generated by
tools/make_scenarios.py) and user-saved scenarios (SCRAMBOX_USER_DIR/scenarios).

A scenario is {"id", "category", "name": {en, zh}, "summary": {en, zh}, "tags",
"notes", "case": <case.json>}. describe() derives the information panel (environment,
background particles and gases, emissions) from the case itself, so it always matches
what the kernel will be given.
"""
from __future__ import annotations

import json
import os
import re
from pathlib import Path

import numpy as np

from . import case as casemod

ROOT = Path(__file__).resolve().parent.parent
BUILTIN_DIR = ROOT / "scenarios"
CATEGORIES = {
    "teaching": {"en": "Teaching", "zh": "教学"},
    "gmd_validation": {"en": "GMD validation", "zh": "GMD 验证"},
    "gmd_reference": {"en": "GMD Greater Paris", "zh": "GMD 巴黎参考"},
    "mixing_state": {"en": "Mixing-state studies", "zh": "混合态研究"},
    "custom": {"en": "My scenarios", "zh": "我的情景"},
}


def user_dir(base: str | Path | None = None) -> Path:
    """Saved scenarios of one user; base = that user's data directory (the server gives
    each signed-in user their own), default SCRAMBOX_USER_DIR or ~/.scrambox."""
    base = Path(base) if base else Path(os.environ.get("SCRAMBOX_USER_DIR", Path.home() / ".scrambox"))
    d = base / "scenarios"
    d.mkdir(parents=True, exist_ok=True)
    return d


def _read(path: Path, builtin: bool) -> dict:
    s = json.loads(path.read_text(encoding="utf-8"))
    s["builtin"] = builtin
    return s


def all_scenarios(base=None) -> list[dict]:
    out = [_read(p, True) for p in sorted(BUILTIN_DIR.glob("*.json"))]
    out += [_read(p, False) for p in sorted(user_dir(base).glob("*.json"))]
    order = list(CATEGORIES)
    out.sort(key=lambda s: (order.index(s.get("category", "custom"))
                            if s.get("category") in order else 99, s["id"]))
    return out


def index(base=None) -> list[dict]:
    return [{k: s.get(k) for k in ("id", "category", "name", "summary", "tags", "builtin")}
            for s in all_scenarios(base)]


def get(sid: str, base=None) -> dict:
    for s in all_scenarios(base):
        if s["id"] == sid:
            return s
    raise KeyError(sid)


def save_user(scn: dict, base=None) -> dict:
    """Save (or overwrite) a user scenario; built-in ids cannot be overwritten."""
    sid = re.sub(r"[^A-Za-z0-9_-]+", "_", scn.get("id") or scn["name"]["en"]).strip("_").lower()
    if not sid:
        raise ValueError("scenario needs an id or a name")
    if (BUILTIN_DIR / f"{sid}.json").exists():
        sid = "my_" + sid
    casemod.resolve(scn["case"])                     # validate
    s = {"id": sid, "category": "custom",
         "name": scn.get("name") or {"en": sid, "zh": sid},
         "summary": scn.get("summary") or {"en": "", "zh": ""},
         "tags": scn.get("tags", []), "notes": scn.get("notes", []),
         "derived_from": scn.get("derived_from"), "case": scn["case"]}
    s["case"].setdefault("case", {}).update({"scenario_id": sid, "category": "custom"})
    (user_dir(base) / f"{sid}.json").write_text(json.dumps(s, indent=1, ensure_ascii=False), encoding="utf-8")
    s["builtin"] = False
    return s


def delete_user(sid: str, base=None) -> None:
    if not re.fullmatch(r"[A-Za-z0-9_-]{1,80}", sid or ""):
        raise KeyError(sid)
    p = user_dir(base) / f"{sid}.json"
    if not p.exists():
        raise KeyError(sid)
    p.unlink()


# ------------------------------------------------------------------ information panel
def _summarise_sections(number, mass, g, per_s=False) -> dict:
    """Totals of a section state: number, PM1 / PM2.5 / PM10 and mass by species."""
    table, bounds = g["table"], g["bounds_um"]
    nsize, nfrac = len(bounds) - 1, len(g["classes"])
    upper = np.repeat(np.array(bounds[1:]), nfrac)
    m = mass.sum(axis=1)
    out = {"number_cm3": float(number.sum() / 1e6),
           "PM1": float(m[upper <= 1.0 + 1e-9].sum()),
           "PM2_5": float(m[upper <= 2.5 + 1e-9].sum()),
           "PM10": float(m[upper <= 10.0 + 1e-9].sum()),
           "total": float(m.sum()),
           "by_species": {s: float(mass[:, i].sum()) for i, s in enumerate(table.aerosol)
                          if mass[:, i].sum() > 0},
           "by_class_number_cm3": [float(number.reshape(nsize, nfrac)[:, c].sum() / 1e6)
                                   for c in range(nfrac)]}
    if per_s:
        out = {k + ("_per_s" if k != "by_class_number_cm3" else ""): v for k, v in out.items()}
    return out


def describe(user_case: dict) -> dict:
    from .compile import build_grid, gas_vector, met_table, particles_to_sections
    c = casemod.resolve(user_case)
    g = build_grid(c)
    table = g["table"]
    n0, m0, notes0 = particles_to_sections(c["initial"]["particles"], g, False, "initial.particles")
    ne, me, notes1 = particles_to_sections(c["emissions"]["particles"], g, True, "emissions.particles")
    gas0 = gas_vector(c["initial"].get("gas_ugm3"), table, "initial.gas_ugm3")
    gsrc = gas_vector(c["emissions"].get("gas_ugm3_s"), table, "emissions.gas_ugm3_s")
    met = met_table(c)
    e, t = c["environment"], c["time"]
    rng = lambda row: [float(met[row].min()), float(met[row].max())]
    return {
        "environment": {"temperature_K": rng(1), "relative_humidity": rng(2), "pressure_Pa": rng(3),
                        "jno2_s1": rng(4), "dilution_s1": rng(7),
                        "time_varying": bool(e.get("time_series"))},
        "time": {"duration_h": t["duration_s"] / 3600.0, "dt_s": t["dt_s"], "substep_s": t["substep_s"],
                 "n_kernel_calls": int(round(t["duration_s"] / t["substep_s"]))},
        "kernel": c["kernel"]["isorropia"],
        "thermodynamics": c["processes"]["thermodynamics"],
        "processes": {"coagulation": c["processes"]["coagulation"],
                      "condensation": c["processes"]["condensation"],
                      "nucleation": c["processes"]["nucleation"]["enabled"]},
        "grid": {"n_size": len(g["bounds_um"]) - 1, "n_class": len(g["classes"]),
                 "d_range_um": [g["bounds_um"][0], g["bounds_um"][-1]], "mixing": c["mixing"]["preset"]},
        "initial_particles": _summarise_sections(n0, m0, g),
        "initial_gas_ugm3": {s: float(v) for s, v in zip(table.gases, gas0) if v > 0},
        "particle_emissions": _summarise_sections(ne, me, g, per_s=True),
        "gas_sources_ugm3_s": {s: float(v) for s, v in zip(table.gases, gsrc) if v > 0},
        "emission_profile": ("time-varying" if c["emissions"].get("time_profile") else "constant"),
        "gas_source_profile": (c["emissions"].get("gas_time_profile") if isinstance(
            c["emissions"].get("gas_time_profile"), str) else
            ("time-varying" if c["emissions"].get("gas_time_profile") else "as particles")),
        "notes": notes0 + notes1,
    }
